# side_by_side_comparison.py
# Run this to see exactly what FastMCP generates behind the scenes
# Install: pip install fastmcp mcp

import asyncio
import json

# ─── FASTMCP INTROSPECTION ────────────────────────────────────────────
# Let us ask FastMCP to show us what it generated for our tools

from fastmcp import FastMCP

mcp = FastMCP("Comparison Server")

@mcp.tool()
def add(a: float, b: float) -> float:
    """Add two numbers. Returns the sum."""
    return a + b

@mcp.tool()
def greet(name: str, formal: bool = False) -> str:
    """
    Greet someone.
    name:   The person's name
    formal: Use formal greeting if True
    """
    return f"Good day, {name}." if formal else f"Hey {name}!"

@mcp.tool()
def process_items(items: list, max_count: int = 10) -> str:
    """
    Process a list of items.
    items:     List of items to process
    max_count: Maximum items to process (default 10)
    """
    processed = items[:max_count]   # Take only up to max_count items
    return f"Processed {len(processed)} items: {processed}"

async def show_generated_schemas():
    """Show what FastMCP auto-generated from our type hints"""
    tools = await mcp.list_tools()   # Get all registered tools

    print("=" * 65)
    print("WHAT FASTMCP AUTO-GENERATED FROM YOUR TYPE HINTS")
    print("=" * 65)

    for tool in tools:
        print(f"\n📦 Tool: {tool.name}")
        print(f"   Description: {tool.description}")
        print(f"   Auto-generated JSON Schema:")

        # Pretty print the schema with indentation
        schema_lines = json.dumps(tool.inputSchema, indent=2).split('\n')
        for line in schema_lines:
            print(f"   {line}")

        print()

asyncio.run(show_generated_schemas())
```

